/**
 * Timestamp helpers: ISO round-tripping, relative formatting, and the calendar
 * arithmetic behind due dates and digest windows.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 *
 * Calendar days are never taken in UTC here. Every day boundary is on the
 * workspace clock: the IANA zone passed in as `timeZone`.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

/** `YYYY-MM-DD` on some zone's calendar. */
type CalendarDay = string;

const zoneFormatters = new Map<string, Intl.DateTimeFormat>();

function formatterFor(timeZone: string): Intl.DateTimeFormat {
  let formatter = zoneFormatters.get(timeZone);
  if (!formatter) {
    // `Intl` throws a RangeError for a zone name it does not recognise, which
    // is the only validation there is, so it happens here before caching.
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    zoneFormatters.set(timeZone, formatter);
  }
  return formatter;
}

/** Throws a `RangeError` for a zone name `Intl` does not recognise. */
export function assertTimeZone(timeZone: string): void {
  formatterFor(timeZone);
}

export function isValidTimeZone(timeZone: string): boolean {
  try {
    assertTimeZone(timeZone);
    return true;
  } catch {
    return false;
  }
}

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * Wall-clock fields of `instant` in `timeZone`. Read through `formatToParts`
 * so no part of the answer depends on the host's own zone.
 */
function wallClock(instant: Date, timeZone: string): Record<string, number> {
  const fields: Record<string, number> = {};
  for (const part of formatterFor(timeZone).formatToParts(instant)) {
    if (part.type !== "literal") fields[part.type] = Number(part.value);
  }
  return fields;
}

/** The zone's offset from UTC at `instantMs`, in milliseconds. */
function offsetMs(instantMs: number, timeZone: string): number {
  const fields = wallClock(new Date(instantMs), timeZone);
  const asUtc = Date.UTC(
    fields.year,
    fields.month - 1,
    fields.day,
    fields.hour,
    fields.minute,
    fields.second,
  );
  return asUtc - Math.floor(instantMs / 1000) * 1000;
}

/**
 * The instant at which `timeZone`'s wall clock reads `day` at `hour:00`.
 * Two passes, so a DST transition between the guess and the answer is caught.
 */
function localHourMs(day: CalendarDay, hour: number, timeZone: string): number {
  const [year, month, date] = day.split("-").map(Number) as [number, number, number];
  const wallMs = Date.UTC(year, month - 1, date, hour);
  const firstGuess = wallMs - offsetMs(wallMs, timeZone);
  return wallMs - offsetMs(firstGuess, timeZone);
}

/** The calendar day `instant` falls on in `timeZone`. */
function dayOf(instant: Date, timeZone: string): CalendarDay {
  const fields = wallClock(instant, timeZone);
  return [
    String(fields.year).padStart(4, "0"),
    String(fields.month).padStart(2, "0"),
    String(fields.day).padStart(2, "0"),
  ].join("-");
}

/** Calendar arithmetic on a `YYYY-MM-DD` string; no zone is involved. */
function shiftDay(day: CalendarDay, days: number): CalendarDay {
  const [year, month, date] = day.split("-").map(Number) as [number, number, number];
  return new Date(Date.UTC(year, month - 1, date + days)).toISOString().slice(0, 10);
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/** The `YYYY-MM-DD` calendar date of `value` on the workspace clock. */
export function localDate(value: IsoTimestamp, timeZone: string): CalendarDay {
  return dayOf(parseIso(value), timeZone);
}

/** The hour (0-23) `instant` shows on the workspace clock. */
export function localHour(instant: Date, timeZone: string): number {
  return wallClock(instant, timeZone).hour;
}

/**
 * The instant the workspace's calendar day containing `reference` began,
 * i.e. its local midnight.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(
    new Date(localHourMs(dayOf(reference, timeZone), 0, timeZone)),
  );
}

/**
 * The local midnight that opens the calendar day `days` before the one that
 * contains `reference`. Counted in calendar days, so a DST change does not
 * shift it by an hour.
 */
export function startOfLocalDaysAgo(
  reference: Date,
  timeZone: string,
  days: number,
): IsoTimestamp {
  const day = shiftDay(dayOf(reference, timeZone), -days);
  return toIsoTimestamp(new Date(localHourMs(day, 0, timeZone)));
}

/**
 * True when a due date exists and its calendar day has ended on the
 * workspace clock. The due day itself is not overdue, whatever time it names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return dayOf(parseIso(dueAt), timeZone) < dayOf(reference, timeZone);
}

/** The time-of-day-free rendering of a due date: `YYYY-MM-DD` in `timeZone`. */
export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers. It ends at the most recent local `digestHour:00`
 * at or before `reference`: today's if that has passed, yesterday's otherwise.
 * It starts at the same local hour on the previous calendar day, so across a
 * DST change the window spans 23 or 25 hours.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  let endDay = dayOf(reference, timeZone);
  let endMs = localHourMs(endDay, digestHour, timeZone);
  if (endMs > reference.getTime()) {
    endDay = shiftDay(endDay, -1);
    endMs = localHourMs(endDay, digestHour, timeZone);
  }

  const startMs = localHourMs(shiftDay(endDay, -1), digestHour, timeZone);

  return {
    start: toIsoTimestamp(new Date(startMs)),
    end: toIsoTimestamp(new Date(endMs)),
  };
}

