 * True when a due date exists and its calendar day has ended on the
 * workspace clock. The due day itself is not overdue, whatever time it names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return dayOf(parseIso(dueAt), timeZone) < dayOf(reference, timeZone);
}

