 * The window a digest covers. It ends at the most recent local `digestHour:00`
 * at or before `reference`: today's if that has passed, yesterday's otherwise.
 * It starts at the same local hour on the previous calendar day, so across a
 * DST change the window spans 23 or 25 hours.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  let endDay = dayOf(reference, timeZone);
  let endMs = localHourMs(endDay, digestHour, timeZone);
  if (endMs > reference.getTime()) {
    endDay = shiftDay(endDay, -1);
    endMs = localHourMs(endDay, digestHour, timeZone);
  }

  const startMs = localHourMs(shiftDay(endDay, -1), digestHour, timeZone);

  return {
    start: toIsoTimestamp(new Date(startMs)),
    end: toIsoTimestamp(new Date(endMs)),
  };
}

