/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * Wall-clock fields of `instant` in `timeZone`. Read through `formatToParts`
 * so no part of the answer depends on the host's own zone.
 */
function wallClock(instant: Date, timeZone: string): Record<string, number> {
  const fields: Record<string, number> = {};
  for (const part of formatterFor(timeZone).formatToParts(instant)) {
    if (part.type !== "literal") fields[part.type] = Number(part.value);
  }
  return fields;
}

/** The zone's offset from UTC at `instantMs`, in milliseconds. */
function offsetMs(instantMs: number, timeZone: string): number {
  const fields = wallClock(new Date(instantMs), timeZone);
  const asUtc = Date.UTC(
    fields.year,
    fields.month - 1,
    fields.day,
    fields.hour,
    fields.minute,
    fields.second,
  );
  return asUtc - Math.floor(instantMs / 1000) * 1000;
}

/**
 * The instant at which `timeZone`'s wall clock reads `day` at `hour:00`.
 * Two passes, so a DST transition between the guess and the answer is caught.
 */
function localHourMs(day: CalendarDay, hour: number, timeZone: string): number {
  const [year, month, date] = day.split("-").map(Number) as [number, number, number];
  const wallMs = Date.UTC(year, month - 1, date, hour);
  const firstGuess = wallMs - offsetMs(wallMs, timeZone);
  return wallMs - offsetMs(firstGuess, timeZone);
}

/** The calendar day `instant` falls on in `timeZone`. */
function dayOf(instant: Date, timeZone: string): CalendarDay {
  const fields = wallClock(instant, timeZone);
  return [
    String(fields.year).padStart(4, "0"),
    String(fields.month).padStart(2, "0"),
    String(fields.day).padStart(2, "0"),
  ].join("-");
}

