it("treats a null due date as never overdue", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
});

it("is not overdue on the due day itself, whatever time it names", () => {
  expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T23:59:59.000Z"), REFERENCE)).toBe(false);
});

it("is overdue once the due day has ended", () => {
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  expect(isOverdue(iso("2026-03-16T00:00:00.000Z"), REFERENCE)).toBe(false);
});

it("decides the due day on the workspace clock", () => {
  // 15 Mar 05:00 in Tokyo; the Tokyo day is still 15 Mar at 23:00 JST.
  const dueAt = iso("2026-03-14T20:00:00.000Z");
  const tokyoLateOn15th = new Date("2026-03-15T14:00:00.000Z");
  expect(isOverdue(dueAt, tokyoLateOn15th, "Asia/Tokyo")).toBe(false);
  // The UTC day of the same instant is 14 Mar, which has ended.
  expect(isOverdue(dueAt, tokyoLateOn15th)).toBe(true);
  // Midnight in Tokyo is 15:00Z on the 15th, when the due day has ended.
  expect(isOverdue(dueAt, new Date("2026-03-15T15:00:00.000Z"), "Asia/Tokyo")).toBe(true);
});

it("reads calendar days on a zone's clock", () => {
  const instant = iso("2026-03-14T20:00:00.000Z");
  expect(localDate(instant, "UTC")).toBe("2026-03-14");
  expect(localDate(instant, "Asia/Tokyo")).toBe("2026-03-15");
  expect(localDate(instant, "America/New_York")).toBe("2026-03-14");
  expect(localHour(new Date(instant), "Asia/Tokyo")).toBe(5);
});

it("starts the local day at local midnight", () => {
  expect(startOfLocalDay(new Date("2026-03-14T20:00:00.000Z"), "Asia/Tokyo")).toBe(
    "2026-03-14T15:00:00.000Z",
  );
  // 8 Mar 2026 is the US spring-forward day; midnight is still standard time.
  expect(startOfLocalDay(new Date("2026-03-08T15:00:00.000Z"), "America/New_York")).toBe(
    "2026-03-08T05:00:00.000Z",
  );
});

it("counts retention in calendar days on the zone's clock", () => {
  expect(
    startOfLocalDaysAgo(REFERENCE, "America/New_York", 2),
  ).toBe("2026-03-13T04:00:00.000Z");
});

it("recognises IANA zone names and refuses the rest", () => {
  expect(isValidTimeZone("Asia/Tokyo")).toBe(true);
  expect(isValidTimeZone("Mars/Olympus")).toBe(false);
  expect(() => assertTimeZone("Mars/Olympus")).toThrow(RangeError);
});

