it("rejects a digest hour outside 0-23", () => {
  expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
  expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
});

it("ends the digest window at the local digest hour in the workspace zone", () => {
  // 09:00 JST on 15 Mar: today's 08:00 JST has passed.
  const window = digestWindow(8, new Date("2026-03-15T00:00:00.000Z"), "Asia/Tokyo");
  expect(window.end).toBe("2026-03-14T23:00:00.000Z");
  expect(window.start).toBe("2026-03-13T23:00:00.000Z");
});

it("spans 23 hours across the spring-forward change", () => {
  // 06:00 EDT on 9 Mar: today's 01:00 EDT has passed.
  const window = digestWindow(1, new Date("2026-03-09T10:00:00.000Z"), "America/New_York");
  expect(window.end).toBe("2026-03-09T05:00:00.000Z");
  expect(window.start).toBe("2026-03-08T06:00:00.000Z");
  expect(parseIso(window.end).getTime() - parseIso(window.start).getTime()).toBe(23 * 3_600_000);
});

it("spans 25 hours across the fall-back change", () => {
  // 07:00 EST on 2 Nov: today's 01:00 EST has passed.
  const window = digestWindow(1, new Date("2026-11-02T12:00:00.000Z"), "America/New_York");
  expect(window.end).toBe("2026-11-02T06:00:00.000Z");
  expect(window.start).toBe("2026-11-01T05:00:00.000Z");
  expect(parseIso(window.end).getTime() - parseIso(window.start).getTime()).toBe(25 * 3_600_000);
});

