/**
 * Workspace time zones: stored with the other settings, refused before any write.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { organizationSettingsSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("organization time zones", () => {
  it("defaults new workspaces to UTC", async () => {
    const tenant = await createTenant("tz-default");

    expect(tenant.org.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("UTC");
  });

  it("stores a zone with the other settings", async () => {
    const tenant = await createTenant("tz-store");

    const updated = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo" },
    });

    expect(updated.settings.timeZone).toBe("Asia/Tokyo");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");
  });

  it("refuses an unknown zone with a RangeError and changes nothing", async () => {
    const tenant = await createTenant("tz-refuse");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { timeZone: "Europe/Berlin", digestHourUtc: 9 },
    });

    await expect(
      orgRepo.updateOrg(tenant.org.id, {
        orgId: tenant.org.id,
        settings: { timeZone: "Mars/Olympus", digestHourUtc: 10 },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    const stored = await orgRepo.findOrgById(tenant.org.id);
    expect(stored?.settings.timeZone).toBe("Europe/Berlin");
    expect(stored?.settings.digestHourUtc).toBe(9);
  });

  it("the settings schema defaults to UTC and rejects unknown zones", () => {
    expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
    expect(organizationSettingsSchema.safeParse({ timeZone: "Asia/Tokyo" }).success).toBe(true);
    expect(organizationSettingsSchema.safeParse({ timeZone: "Mars/Olympus" }).success).toBe(false);
  });
});

